export function manualPlacementSummary(mode: WindowsDisplayMode): string {
  if (mode === "duplicate") {
    return "Manual placement: keep this public Stage as the only session on this PC; use a separate controller, then enter fullscreen.";
  }
  if (mode === "single") {
    return "Manual placement: keep Stage as the only app on the audience screen, then enter fullscreen.";
  }
  return "Manual placement: drag this public Stage to the target screen, then enter fullscreen.";
}

export function emergencyPublicSlideSet(
  event: Pick<KeyboardEvent, "key" | "altKey" | "ctrlKey" | "metaKey" | "shiftKey">,
  orderedPublicSlideKeys: readonly string[],
  currentPublicSlideKey: string,
): PublicSlideSet | null {
  if (
    event.altKey ||
    event.ctrlKey ||
    event.metaKey ||
    event.shiftKey ||
    orderedPublicSlideKeys.length === 0
  ) {
    return null;
  }
  const currentIndex = Math.max(0, orderedPublicSlideKeys.indexOf(currentPublicSlideKey));
  let nextIndex: number;
  switch (event.key) {
    case "ArrowRight":
    case "PageDown":
      nextIndex = Math.min(orderedPublicSlideKeys.length - 1, currentIndex + 1);
      break;
    case "ArrowLeft":
    case "PageUp":
      nextIndex = Math.max(0, currentIndex - 1);
      break;
    case "Home":
      nextIndex = 0;
      break;
    case "End":
      nextIndex = orderedPublicSlideKeys.length - 1;
      break;
    default:
      return null;
  }
  const publicSlideKey = orderedPublicSlideKeys[nextIndex];
  return publicSlideKey === undefined
    ? null
    : { kind: "PUBLIC_SLIDE_ABSOLUTE_SET", publicSlideKey };
}

